class cbVector
{
    unsigned char pData[4];
};

template <class Type> class Table
{
    Type data[16];
    int size;
public:
    virtual ~Table();
    Type &operator[](const int i);
};

class CodeBook
{
    Table<cbVector> VectList;
    Table<int> usageCount;
public:
    virtual ~CodeBook();
    int FindVectorSlow(const cbVector &Vect);
    cbVector &operator[](const int i) { return VectList[i]; }
};

class DXT1Color
{
public:
    DXT1Color() {}
    union {
        struct { unsigned char r, g, b, a; };
        unsigned int Col;
    };
};

class ImageDXTC
{
    static const unsigned short ColorBits3[3];
    int XSize, YSize;
    unsigned char AlphaValue;

    unsigned short Make565(const DXT1Color & Col) const
    {
        return ((unsigned short)(Col.r >> 3) << 11) | ((unsigned short)(Col.g >> 2) << 5) | ((unsigned short)(Col.b >> 3));
    }

public:
    void EmitMultiColorBlock3(unsigned short *pDest, CodeBook &cb, DXT1Color *pSrc);
};

void ImageDXTC::EmitMultiColorBlock3(unsigned short *pDest, CodeBook &cb, DXT1Color *pSrc)
{
int x, y, Shift;
unsigned short Index, Col1, Col2;
DXT1Color C, C2;

	C = *((DXT1Color *)&cb[0]);
	C2 = *((DXT1Color *)&cb[2]);

	Col1 = Make565(C);
	Col2 = Make565(C2);

	if(Col1 > Col2)
	{
		*((DXT1Color *)&cb[0]) = C2;
		*((DXT1Color *)&cb[2]) = C;		// Shuffle the color table order around
		pDest[0] = Col2;
		pDest[1] = Col1;
	}
	else
	{
		pDest[0] = Col1;
		pDest[1] = Col2;
	}

	pDest[2] = 0;
	pDest[3] = 0;
	pDest += 2;

	unsigned char *pcDest = (unsigned char *)pDest;
	for(y=0; y<4; y++)
	{
		Shift = 0;
		for(x=0; x<4; x++)
		{
			C = pSrc[x];
			C.a = 0;
			Index = ColorBits3[ cb.FindVectorSlow( *((cbVector *)(&C)) ) ];

			*pcDest |= Index << Shift;
			Shift += 2;
		}
		pSrc += XSize;
		pcDest ++;
	}
}
